/* === KERNEL BEGIN === */
static void kernel(long n, int reps, const long *rowptr, const int *col,
                   const double *val, const double *x, double *y) {
    /* We create the parallel region outside the repetitions loop to avoid the 
       overhead of repeatedly creating and destroying the thread team. */
    #pragma omp parallel
    {
        for (int r = 0; r < reps; r++) {
            /* 
             * The workload per row is highly irregular (heavy-tailed distribution).
             * P-cores are significantly faster than E-cores on the M4.
             * 'guided' scheduling is chosen because it starts with large chunks 
             * to reduce synchronization overhead and progressively reduces chunk 
             * sizes to balance the load. This allows the faster P-cores to 
             * process more rows and handles the irregular row lengths effectively.
             */
            #pragma omp for schedule(guided)
            for (long i = 0; i < n; i++) {
                double s = 0.0;
                long start = rowptr[i];
                long end = rowptr[i + 1];
                for (long k = start; k < end; k++) {
                    s += val[k] * x[col[k]];
                }
                y[i] = s;
            }
        }
    }
}
